
"use client";

import { useState } from "react";
import {
  Phone, Wallet, History, Settings, Globe2, ChevronDown,
  Plus, Delete, Mic, Volume2, Grid3X3, PhoneOff,
  Clock, ArrowDownLeft, ArrowUpRight, Menu, X
} from "lucide-react";

const destinations = [
  { name: "Eritrea", code: "+291", flag: "🇪🇷" },
  { name: "Ethiopia", code: "+251", flag: "🇪🇹" },
  { name: "Sudan", code: "+249", flag: "🇸🇩" },
  { name: "Kenya", code: "+254", flag: "🇰🇪" },
];

const recentCalls = [
  { name: "Recent contact", number: "+291 7XX XXX XX", date: "Demo history", duration: "—" },
  { name: "Recent contact", number: "+291 1XX XXX XX", date: "Demo history", duration: "—" },
  { name: "Recent contact", number: "+251 9XX XXX XX", date: "Demo history", duration: "—" },
];

export default function Home() {
  const [destination, setDestination] = useState("Eritrea");
  const [phone, setPhone] = useState("");
  const [activeTab, setActiveTab] = useState("Dialer");
  const [notice, setNotice] = useState("");
  const [menuOpen, setMenuOpen] = useState(false);

  const selected = destinations.find((d) => d.name === destination)!;

  function addDigit(digit: string) {
    setPhone((previous) => previous + digit);
    setNotice("");
  }

  function handleCall() {
    if (!phone.trim()) {
      setNotice("Enter a phone number first.");
      return;
    }
    setNotice("Demo only — calling is not connected yet.");
  }

  const keypad = ["1", "2", "3", "4", "5", "6", "7", "8", "9", "*", "0", "#"];

  return (
    <main className="dashboard">
      <aside className={`sidebar ${menuOpen ? "sidebar-open" : ""}`}>
        <a href="#" className="brand">
          <span className="brand-symbol">D</span>
          <span className="brand-name">DEWL<small>CALL HOME</small></span>
        </a>

        <div className="sidebar-label">WORKSPACE</div>
        {[
          { name: "Dialer", icon: Phone },
          { name: "Call history", icon: History },
          { name: "Wallet", icon: Wallet },
          { name: "Settings", icon: Settings },
        ].map(({ name, icon: Icon }) => (
          <button
            key={name}
            className={`nav-item ${activeTab === name ? "nav-active" : ""}`}
            onClick={() => { setActiveTab(name); setMenuOpen(false); setNotice(""); }}
          >
            <Icon size={19} />
            <span>{name}</span>
          </button>
        ))}

        <div className="sidebar-bottom">
          <div className="support-card">
            <div className="support-icon"><Globe2 size={18} /></div>
            <strong>Stay connected.</strong>
            <p>Call home. Stay close.</p>
          </div>
          <div className="profile">
            <div className="profile-avatar">D</div>
            <div><strong>DEWL account</strong><small>Demo workspace</small></div>
          </div>
        </div>
      </aside>

      {menuOpen && <button className="mobile-overlay" onClick={() => setMenuOpen(false)} aria-label="Close menu" />}

      <section className="main-area">
        <header className="topbar">
          <button className="mobile-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle menu">
            {menuOpen ? <X /> : <Menu />}
          </button>
          <div className="breadcrumb">Workspace <span>/</span> <strong>{activeTab}</strong></div>
          <div className="topbar-right">
            <span className="language"><Globe2 size={16} /> English <ChevronDown size={14} /></span>
            <div className="top-avatar">D</div>
          </div>
        </header>

        <div className="content">
          <div className="welcome-row">
            <div>
              <span className="eyebrow">YOUR PERSONAL CALLING SPACE</span>
              <h1>{activeTab === "Dialer" ? "Make a call." : activeTab}</h1>
              <p>{activeTab === "Dialer" ? "The people who matter are just a call away." : `Manage your DEWL ${activeTab.toLowerCase()}.`}</p>
            </div>
            <div className="balance-card">
              <div className="balance-top"><Wallet size={17} /> WALLET BALANCE</div>
              <div className="balance-amount">€12.50 <span>DEMO</span></div>
              <button className="topup-button" onClick={() => setNotice("Wallet top-up will be available when payments are connected.")}>
                <Plus size={15} /> Add credit
              </button>
            </div>
          </div>

          {activeTab === "Dialer" && (
            <div className="dashboard-grid">
              <section className="dialer-panel">
                <div className="panel-heading">
                  <div><h2>Who would you like to call?</h2><p>Choose a destination and enter a number.</p></div>
                  <span className="secure-label">DEWL DIALER</span>
                </div>

                <label className="field-label">COUNTRY / DESTINATION</label>
                <div className="country-select">
                  <span className="country-flag">{selected.flag}</span>
                  <select value={destination} onChange={(e) => setDestination(e.target.value)}>
                    {destinations.map((d) => <option key={d.name}>{d.name}</option>)}
                  </select>
                  <span className="country-code">{selected.code}</span>
                  <ChevronDown size={17} />
                </div>

                <label className="field-label number-label">PHONE NUMBER</label>
                <div className="number-entry">
                  <span>{selected.code}</span>
                  <input
                    value={phone}
                    onChange={(e) => { setPhone(e.target.value.replace(/[^0-9]/g, "")); setNotice(""); }}
                    placeholder="Enter phone number"
                    inputMode="numeric"
                  />
                  {phone && <button onClick={() => setPhone(phone.slice(0, -1))} aria-label="Delete last digit"><Delete size={18} /></button>}
                </div>

                <div className="keypad">
                  {keypad.map((digit) => (
                    <button key={digit} onClick={() => addDigit(digit)}>
                      <strong>{digit}</strong>
                      {digit === "2" ? <small>ABC</small> : digit === "3" ? <small>DEF</small> : digit === "4" ? <small>GHI</small> : digit === "5" ? <small>JKL</small> : digit === "6" ? <small>MNO</small> : digit === "7" ? <small>PQRS</small> : digit === "8" ? <small>TUV</small> : digit === "9" ? <small>WXYZ</small> : <small>&nbsp;</small>}
                    </button>
                  ))}
                </div>

                <button className="call-button" onClick={handleCall}>
                  <Phone size={19} fill="currentColor" /> Call now
                </button>
                {notice && <div className="notice" role="status">{notice}</div>}
                <div className="dialer-footer"><span><Globe2 size={14} /> Calling {destination}</span><span>Rates coming soon</span></div>
              </section>

              <aside className="right-column">
                <section className="info-panel">
                  <div className="info-heading"><h3>Destination rates</h3><Globe2 size={18} /></div>
                  <p className="info-description">Check the applicable rate before connecting.</p>
                  {destinations.map((d) => (
                    <div className="rate-row" key={d.name}>
                      <span>{d.flag} {d.name}</span>
                      <strong>Coming soon</strong>
                    </div>
                  ))}
                  <div className="rate-note">Rates will be confirmed before launch.</div>
                </section>

                <section className="info-panel recent-panel">
                  <div className="info-heading"><h3>Recent calls</h3><button onClick={() => setActiveTab("Call history")}>View all</button></div>
                  {recentCalls.slice(0, 3).map((call, index) => (
                    <div className="recent-row" key={index}>
                      <div className="recent-icon"><ArrowUpRight size={17} /></div>
                      <div className="recent-detail"><strong>{call.name}</strong><small>{call.number}</small></div>
                      <span className="recent-time">{call.duration}</span>
                    </div>
                  ))}
                  <p className="demo-note">Illustrative entries only. Your call history will appear here.</p>
                </section>

                <section className="help-panel">
                  <div className="help-icon"><Phone size={19} /></div>
                  <div><strong>Call home. Stay connected.</strong><p>DEWL makes staying in touch simpler.</p></div>
                </section>
              </aside>
            </div>
          )}

          {activeTab === "Call history" && (
            <section className="simple-panel">
              <div className="info-heading"><h2>Call history</h2><Clock size={19} /></div>
              <p>Your completed calls will appear here once calling is activated.</p>
              {recentCalls.map((call, index) => (
                <div className="history-row" key={index}>
                  <ArrowUpRight size={18} />
                  <div><strong>{call.name}</strong><small>{call.number}</small></div>
                  <span>{call.date}</span>
                </div>
              ))}
              <span className="demo-note">These are illustrative entries, not actual calls.</span>
            </section>
          )}

          {activeTab === "Wallet" && (
            <section className="simple-panel wallet-page">
              <div className="info-heading"><h2>Your wallet</h2><Wallet size={20} /></div>
              <span className="eyebrow">DEMO BALANCE</span>
              <div className="wallet-large">€12.50</div>
              <p>Payments and wallet transactions will be enabled in a later stage.</p>
              <button className="call-button wallet-topup" onClick={() => setNotice("Payment integration is not connected yet.")}><Plus size={18} /> Add credit</button>
              {notice && <div className="notice">{notice}</div>}
            </section>
          )}

          {activeTab === "Settings" && (
            <section className="simple-panel">
              <div className="info-heading"><h2>Settings</h2><Settings size={20} /></div>
              <p>Account settings and language preferences will be available here.</p>
              <div className="history-row"><Globe2 size={18} /><div><strong>Language</strong><small>English</small></div><span>Coming soon</span></div>
            </section>
          )}

          <footer className="app-footer">
            <span>© 2026 DEWL</span>
            <span>Call home. Stay connected. Pay less.</span>
            <span>Demo interface · Calling not connected</span>
          </footer>
        </div>
      </section>
    </main>
  );
}
